// runningList returns the list of running tests.
func windows_runningList() []string {
	var list []string
	running.Range(func(k, v any) bool {
		list = append(list, fmt.Sprintf("%s (%v)", k.(string), windows_highPrecisionTimeSince(v.(windows_highPrecisionTime)).Round(time.Second)))
		return true
	})
	slices.Sort(list)
	return list
}/*line testing.go:2984:2*//*line testing.go:3002:2*//*line testing.go:3006:2*/
